import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { CatalogController } from './catalog.controller';
import { CatalogService } from './catalog.service';
import { Category } from './category.entity';
import { Product } from './product.entity';

@Module({
  imports: [TypeOrmModule.forFeature([Category, Product])],
  controllers: [CatalogController],
  providers: [CatalogService],
  exports: [CatalogService],
})
export class CatalogModule {}

import { Injectable, Logger, NotFoundException, OnModuleInit } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { CATEGORY_SEED, PRODUCT_SEED } from './catalog.seed';
import { Category } from './category.entity';
import { Product } from './product.entity';

@Injectable()
export class CatalogService implements OnModuleInit {
  private readonly logger = new Logger(CatalogService.name);

  constructor(
    @InjectRepository(Category) private readonly categories: Repository<Category>,
    @InjectRepository(Product) private readonly products: Repository<Product>,
  ) {}

  async onModuleInit(): Promise<void> {
    const count = await this.products.count();
    if (count > 0) {
      this.logger.log(`Catalog already has ${count} products`);
      return;
    }
    const savedCategories = await this.categories.save(
      CATEGORY_SEED.map((c) => this.categories.create(c)),
    );
    const bySlug = new Map(savedCategories.map((c) => [c.slug, c]));
    for (const seed of PRODUCT_SEED) {
      await this.products.save(
        this.products.create({
          sku: seed.sku,
          name: seed.name,
          priceCents: seed.priceCents,
          category: bySlug.get(seed.category),
        }),
      );
    }
    this.logger.log(`Seeded ${savedCategories.length} categories and ${PRODUCT_SEED.length} products`);
  }

  findAll(): Promise<Product[]> {
    return this.products.find({ relations: { category: true }, order: { sku: 'ASC' } });
  }

  async findOne(id: string): Promise<Product> {
