import {
  BadRequestException,
  forwardRef,
  Inject,
  Injectable,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AuditService } from '../audit/audit.service';
import { CatalogService } from '../catalog/catalog.service';
import { PaymentsService } from '../payments/payments.service';
import { UsersService } from '../users/users.service';
import { CreateOrderDto } from './create-order.dto';
import { OrderItem } from './order-item.entity';
import { Order } from './order.entity';

@Injectable()
export class OrdersService {
  private readonly logger = new Logger(OrdersService.name);

  constructor(
    @InjectRepository(Order) private readonly orders: Repository<Order>,
    @InjectRepository(OrderItem) private readonly items: Repository<OrderItem>,
    private readonly usersService: UsersService,
    private readonly catalogService: CatalogService,
    private readonly audit: AuditService,
    @Inject(forwardRef(() => PaymentsService))
    private readonly paymentsService: PaymentsService,
  ) {}

  findAll(): Promise<Order[]> {
    return this.orders.find({
      relations: { user: true, items: { product: true } },
      order: { createdAt: 'DESC' },
    });
  }

  async findOne(id: string): Promise<Order> {
    const order = await this.orders.findOne({
      where: { id },
      relations: { user: true, items: { product: true } },
    });
    if (!order) {
      throw new NotFoundException(`Order ${id} not found`);
    }
    return order;
  }

  async create(dto: CreateOrderDto): Promise<Order> {
    const user = await this.usersService.findOne(dto.userId);
    const products = await this.catalogService.findByIds(dto.lines.map((l) => l.productId));
    if (products.length !== dto.lines.length) {
      throw new BadRequestException('One or more products do not exist');
    }
    const byId = new Map(products.map((p) => [p.id, p]));
    const items = dto.lines.map((line) => {
      const product = byId.get(line.productId);
      return this.items.create({
        product,
        quantity: line.quantity,
        unitPriceCents: product.priceCents,
      });
    });
    const totalCents = items.reduce((sum, item) => sum + item.quantity * item.unitPriceCents, 0);
    const order = await this.orders.save(this.orders.create({ user, items, totalCents }));
    await this.audit.record('order.created', user.email, { orderId: order.id, totalCents });
    this.logger.log(`Order ${order.id} created for ${user.email} (${totalCents} cents)`);
    return order;
  }

  async pay(id: string, provider = 'card'): Promise<Order> {
    const order = await this.findOne(id);
    if (order.status !== 'pending') {
      throw new BadRequestException(`Order ${id} is ${order.status}, cannot pay`);
    }
    await this.paymentsService.charge(order, provider);
    order.status = 'paid';
    await this.orders.save(order);
    await this.audit.record('order.paid', order.user.email, { orderId: order.id, provider });
    return order;
  }

  async markRefunded(id: string): Promise<void> {
    await this.orders.update({ id }, { status: 'refunded' });
  }
}

