import {
  BadRequestException,
  forwardRef,
  Inject,
  Injectable,
  Logger,
  NotFoundException,
  OnModuleInit,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { NotificationsService } from '../notifications/notifications.service';
import { Order } from '../orders/order.entity';
import { Invoice } from './invoice.entity';
import { Payment } from './payment.entity';

@Injectable()
export class PaymentsService implements OnModuleInit {
  private readonly logger = new Logger(PaymentsService.name);
  // Pending amount per order id, warmed at boot so refunds can check quickly.
  private readonly pendingByOrder = new Map<string, number>();

  constructor(
    @InjectRepository(Payment) private readonly payments: Repository<Payment>,
    @InjectRepository(Invoice) private readonly invoices: Repository<Invoice>,
    @Inject(forwardRef(() => NotificationsService))
    private readonly notifications: NotificationsService,
  ) {}

  async onModuleInit(): Promise<void> {
    const pending = await this.payments.find({
      where: { status: 'pending' },
      relations: { order: true },
    });
    for (const payment of pending) {
      this.pendingByOrder.set(payment.order.id, payment.amountCents);
    }
    const total = await this.payments.count();
    this.logger.log(`Warmed ${pending.length} pending payments (${total} total)`);
  }

  findAll(): Promise<Payment[]> {
    return this.payments.find({ relations: { order: true }, order: { createdAt: 'DESC' } });
  }

  async charge(order: Order, provider: string): Promise<Payment> {
    const payment = await this.payments.save(
      this.payments.create({ order, provider, amountCents: order.totalCents, status: 'captured' }),
    );
    const invoice = await this.invoices.save(
      this.invoices.create({ order, number: this.nextInvoiceNumber(), issuedAt: new Date() }),
    );
    this.pendingByOrder.delete(order.id);
    await this.notifications.enqueue('receipt', {
      orderId: order.id,
      paymentId: payment.id,
      invoiceNumber: invoice.number,
    });
    return payment;
  }

  async refund(paymentId: string): Promise<Payment> {
    const payment = await this.payments.findOne({ where: { id: paymentId }, relations: { order: true } });
    if (!payment) {
      throw new NotFoundException(`Payment ${paymentId} not found`);
    }
    if (payment.status !== 'captured') {
      throw new BadRequestException(`Payment ${paymentId} is ${payment.status}, cannot refund`);
    }
    payment.status = 'refunded';
    await this.payments.save(payment);
    await this.notifications.enqueue('refund', { orderId: payment.order.id, paymentId });
    return payment;
  }

  private nextInvoiceNumber(): string {
    const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    return `INV-${stamp}-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;
  }
}

