import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

export interface DatabaseOptions {
  host: string;
  port: number;
  username: string;
  password: string;
  database: string;
}

export interface RedisOptions {
  host: string;
  port: number;
}

@Injectable()
export class AppConfigService {
  constructor(private readonly config: ConfigService) {}

  databaseOptions(): DatabaseOptions {
    return {
      host: this.config.getOrThrow<string>('DATABASE_HOST'),
      port: Number(this.config.getOrThrow<string>('DATABASE_PORT')),
      username: this.config.getOrThrow<string>('DATABASE_USER'),
      password: this.config.getOrThrow<string>('DATABASE_PASSWORD'),
      database: this.config.getOrThrow<string>('DATABASE_NAME'),
    };
  }

  redisOptions(): RedisOptions {
    return {
      host: this.config.getOrThrow<string>('REDIS_HOST'),
      port: Number(this.config.getOrThrow<string>('REDIS_PORT')),
    };
  }

  get port(): number {
    return Number(this.config.get<string>('PORT') ?? 3000);
  }
}

